func mergeIntervals(_ intervals: [[Int]]) -> [[Int]] {
    guard !intervals.isEmpty else { return [] }

    let sorted = intervals.sorted { $0[0] < $1[0] }
    var merged = [sorted[0]]

    for i in 1..<sorted.count {
        let current = sorted[i]
        var last = merged[merged.count - 1]

        if current[0] <= last[1] { // Overlapping
            last[1] = max(last[1], current[1])
            merged[merged.count - 1] = last
        } else {
            merged.append(current)
        }
    }

    return merged
}
```

Here's a clean Swift implementation:

```swift
func mergeIntervals(_ intervals: [[Int]]) -> [[Int]] {
    guard !intervals.isEmpty else { return [] }

    // Sort by start value
    let sorted = intervals.sorted { $0[0] < $1[0] }

    var merged: [[Int]] = [sorted[0]]

    for interval in sorted.dropFirst() {
        let lastIndex = merged.count - 1

        if interval[0] <= merged[lastIndex][1] {
            // Overlap: extend the end of the last merged interval
            merged[lastIndex][1] = max(merged[lastIndex][1], interval[1])
        } else {
            // No overlap: start a new interval
            merged.append(interval)
        }
    }

    return merged
}

// Example
print(mergeIntervals([[1,3],[2,6],[8,10]]))  // [[1, 6], [8, 10]]
```

**How it works:**

1. **Sort** the intervals by their start value so overlapping ones are adjacent.
2. **Iterate** through them, comparing each interval's start to the end of the last merged interval.
3. **Merge** if they overlap (`start <= lastEnd`) by taking the larger of the two ends; otherwise **append** it as a new interval.

**Complexity:**
- Time: **O(n log n)**, dominated by sorting
- Space: **O(n)** for the output

**Notes:**
- Intervals that merely touch, like `[1,4]` and `[4,5]`, are merged into `[1,5]`. Change `<=` to `<` if you don't want that.
- Unsorted input like `[[8,10],[1,3],[2,6]]` works fine.

If you want a more type-safe version, you could use a struct or tuple instead of `[Int]`:

```swift
struct Interval {
    var start: Int
    var end: Int
}

func merge(_ intervals: [Interval]) -> [Interval] {
    var result: [Interval] = []

    for interval in intervals.sorted(by: { $0.start < $1.start }) {
        if let last = result.last, interval.start <= last.end {
            result[result.count - 1].end = max(last.end, interval.end)
        } else {
            result.append(interval)
        }
    }

    return result
}
```
